interface I18nContextType {
  lang: Langue;
  setLang: (l: Langue) => void;
  t: (cle: string) => string;
}

const I18nContext = createContext<I18nContextType>({
  lang: "fr",
  setLang: () => {},
  t: (cle: string) => DICO[cle]?.fr ?? cle,
});

export function useI18n() {
  return useContext(I18nContext);
}

// Langue courante hors React (pour les plugins/exécuteurs qui n'ont pas de hook).
// Même source que le provider (localStorage) → reste cohérent avec le toggle.
export function langueCourante(): Langue {
  try {
    if (typeof localStorage !== "undefined" && localStorage.getItem) {
      return (localStorage.getItem(LANG_KEY) as Langue) || "fr";
    }
  } catch { /* SSR/tests sans localStorage */ }
  return "fr";
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Langue>(
    () => {
      try {
        if (typeof localStorage !== "undefined" && localStorage.getItem) {
          return (localStorage.getItem(LANG_KEY) as Langue) || "fr";
        }
      } catch { /* SSR/tests */ }
      return "fr";
    }
  );

  const setLang = useCallback((l: Langue) => {
    setLangState(l);
    localStorage.setItem(LANG_KEY, l);
  }, []);

  const t = useCallback((cle: string) => {
    return DICO[cle]?.[lang] ?? cle;
  }, [lang]);

  return (
    <I18nContext.Provider value={{ lang, setLang, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function traduire(cle: string, ...args: (string | number)[]): string {
  const lang = langueCourante();
  const s = DICO_RUNTIME[cle]?.[lang] ?? DICO_RUNTIME[cle]?.fr ?? DICO[cle]?.[lang] ?? DICO[cle]?.fr ?? cle;
  return s.replace(/\{__VAR_(\d+)__\}/g, (_, i) => {
    const idx = Number(i);
    return args.length > idx ? String(args[idx]) : `{__VAR_${idx}__}`;
  });
}

export function defautParametre(p: Pick<ParametreDef, "defaut" | "defautEn">, lang: Langue): string | number {
  return lang === "en" && p.defautEn !== undefined ? p.defautEn : p.defaut;
}

/**
 * Retourne la valeur canonique (id stable) d'un paramètre de type "choix".
 * Accepte indifféremment l'id canonique, la valeur française ou la valeur anglaise,
 * ce qui garantit la compatibilité avec les anciens projets.
 */
export function valeurCanoniqueChoix(p: Pick<ParametreDef, "options" | "optionsEn" | "optionIds">, valeur: string | number): string | number {
  const ids = p.optionIds;
  if (!ids || ids.length === 0) return valeur;
  const v = String(valeur);
  if (ids.includes(v)) return v;
  const idx = p.options?.indexOf(v) ?? -1;
  if (idx >= 0 && ids[idx] !== undefined) return ids[idx];
  const idxEn = p.optionsEn?.indexOf(v) ?? -1;
  if (idxEn >= 0 && ids[idxEn] !== undefined) return ids[idxEn];
  return v;
}

// VOLONTAIREMENT indépendant de la langue : la forme canonique d'un paramètre
// « choix » est toujours celle de la liste `options` (française), jamais celle
// de `optionsEn`. En effet, sans `optionIds`, l'Inspector rend
// `<option value={p.options[i]}>{libellé traduit}</option>` : seul le LIBELLÉ
// est traduit, la valeur stockée reste le terme français. Partir de `defautEn`
// (par ex. "Center") produisait donc une valeur absente des
// <option value="Gauche"|"Centre"|"Droite"> : un <select> contrôlé sans option
// correspondante retombe silencieusement sur son 1er <option> (« Gauche »),
// alors que l'exécution du nœud, elle, utilisait bien "Centre" — d'où un
// défaut affiché ≠ défaut réellement appliqué. Avec `optionIds`,
// valeurCanoniqueChoix sait mapper le terme français vers l'id : correct aussi.
export function defautCanoniqueChoix(p: Pick<ParametreDef, "defaut" | "defautEn" | "options" | "optionsEn" | "optionIds">): string | number {
  return valeurCanoniqueChoix(p, p.defaut);
}
